<script setup lang="ts">import { onMounted, ref } from 'vue'; import axios from 'axios'; import api from '../plugins/axios'; const desde=ref(new Date(Date.now()-30*86400000).toISOString().slice(0,10)); const hasta=ref(new Date().toISOString().slice(0,10)); const resumen=ref<any>(null); const detalle=ref<any[]>([]); const error=ref(''); async function cargar(){try{const params={desde:desde.value,hasta:hasta.value}; resumen.value=(await api.get('/reportes/ventas',{params})).data; detalle.value=(await api.get('/reportes/ventas/detalle',{params})).data}catch(e){error.value=axios.isAxiosError(e)?e.response?.data?.message??'No se pudo cargar el reporte.':'No se pudo cargar el reporte.'}} onMounted(cargar)</script>
<template><section class="container py-5"><h1 class="h2 fw-bold mb-4">Reportes de ventas</h1><div class="row g-2 mb-4"><div class="col-md-4"><label class="form-label">Desde</label><input v-model="desde" class="form-control" type="date" /></div><div class="col-md-4"><label class="form-label">Hasta</label><input v-model="hasta" class="form-control" type="date" /></div><div class="col-md-4 d-flex align-items-end"><button class="btn btn-primary" type="button" @click="cargar">Consultar</button></div></div><div v-if="error" class="alert alert-danger">{{ error }}</div><div v-if="resumen" class="row g-3 mb-4"><div class="col-md-4"><div class="card border-0 shadow-sm"><div class="card-body"><span>Total cobrado</span><h2 class="h4">{{ resumen.totalCobrado }} Bs</h2></div></div></div><div class="col-md-4"><div class="card border-0 shadow-sm"><div class="card-body"><span>Reembolsos</span><h2 class="h4">{{ resumen.totalReembolsos }} Bs</h2></div></div></div><div class="col-md-4"><div class="card border-0 shadow-sm"><div class="card-body"><span>Neto</span><h2 class="h4">{{ resumen.neto }} Bs</h2></div></div></div></div><div class="table-responsive"><table class="table"><thead><tr><th>Pedido</th><th>Cliente</th><th>Fecha</th><th>Total</th><th>Estado</th></tr></thead><tbody><tr v-for="pedido in detalle" :key="pedido.idPedido"><td>#{{ pedido.idPedido }}</td><td>{{ pedido.cliente?.nombreCompleto || pedido.cliente?.celular }}</td><td>{{ pedido.fechaCompra }}</td><td>{{ Number(pedido.total).toFixed(2) }} Bs</td><td>{{ pedido.estado }}</td></tr></tbody></table></div></section></template>
